'use strict';

const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const jsonPath = path.join(root, 'shared', 'thread_design.json');
const outputPath = path.join(root, 'simulator', 'thread_design.js');
const check = process.argv.includes('--check');
const contract = JSON.parse(fs.readFileSync(jsonPath, 'utf8'));

const output = `'use strict';
// Generated from shared/thread_design.json by scripts/gen-thread-design.js.
// Do not edit this file directly; the JSON contract is the normative source.
(function (root, factory) {
    var raw = ${JSON.stringify(contract, null, 4)};
    var design = factory(raw);
    if (typeof module !== 'undefined' && module.exports) module.exports = design;
    if (root) root.ThreadDesign = design;
})(typeof globalThis !== 'undefined' ? globalThis : this, function (raw) {
    function layout(lumpSize, stackWords, heapWords) {
        lumpSize = Number(lumpSize);
        stackWords = Number(stackWords);
        heapWords = Number(heapWords);
        var capsStart = raw.capabilityHomes.offset;
        var capsEnd = capsStart + raw.capabilityHomes.words - 1;
        var heapStart = raw.heapOffset;
        var heapEnd = heapStart + heapWords - 1;
        var stackEnd = capsStart - 1;
        var stackStart = capsStart - stackWords;
        var freeStart = heapEnd + 1;
        var freeEnd = stackStart - 1;
        var supported = raw.supportedBodyWords.indexOf(lumpSize) !== -1;
        var valid = supported && stackWords > 0 && heapWords > 0 &&
            heapEnd < stackStart && capsEnd < raw.privateAbiWords;
        return Object.freeze({
            valid: valid,
            sizeSupported: supported,
            lumpSize: lumpSize,
            headerOffset: raw.headerOffset,
            drStart: raw.dataRegisters.offset,
            drEnd: raw.dataRegisters.offset + raw.dataRegisters.words - 1,
            drWords: raw.dataRegisters.words,
            protectedStoOffset: raw.protectedStoOffset,
            protectedIndicator: raw.protectedIndicator,
            heapStart: heapStart,
            heapEnd: heapEnd,
            heapWords: heapWords,
            freeStart: freeStart,
            freeEnd: freeEnd,
            freeWords: Math.max(0, freeEnd - freeStart + 1),
            stackStart: stackStart,
            stackEnd: stackEnd,
            stackWords: stackWords,
            capsStart: capsStart,
            capsEnd: capsEnd,
            capsWords: raw.capabilityHomes.words,
            privateZoneWords: raw.privateAbiWords
        });
    }
    return Object.freeze(Object.assign({}, raw, { layout: layout }));
});
`;

if (check) {
    if (!fs.existsSync(outputPath) || fs.readFileSync(outputPath, 'utf8') !== output) {
        console.error('simulator/thread_design.js is stale; run node scripts/gen-thread-design.js');
        process.exit(1);
    }
    console.log('Thread design projection is current');
} else {
    fs.writeFileSync(outputPath, output);
    console.log(`wrote ${path.relative(root, outputPath)}`);
}